package org.springframework.samples.petclinic.service;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single derived key that consolidates owner duplicate detection:
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Because the
 * telephone is part of the key, two members of the same household with different telephones
 * yield different keys and are both allowed; a new owner is a duplicate only when it collides
 * with an existing owner on this key.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        String email = owner.getEmail() == null ? "" : owner.getEmail();
        return owner.getTelephone() + "|" + email + "|" + HouseholdMatcher.householdId(owner);
    }

    public static boolean isDuplicate(Collection<Owner> owners, Owner owner) {
        String key = of(owner);
        return owners.stream().anyMatch(o -> key.equals(of(o)));
    }
}

